import { randomUUID } from "node:crypto";
import type {
  ExtensionAPI,
  SessionBeforeCompactEvent,
  SessionCompactEvent,
  ModelSelectEvent,
  ThinkingLevelSelectEvent,
  SessionBeforeForkEvent,
  SessionTreeEvent,
} from "@earendil-works/pi-coding-agent";
import type { Telemetry } from "../state.ts";
import { guard } from "../state.ts";

function insertEvent(
  t: Telemetry,
  type: string,
  payload: Record<string, unknown>,
): void {
  const sessionId = t.state.sessionId;
  if (!sessionId) return;

  let payloadText: string;
  try {
    payloadText = JSON.stringify(payload);
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err);
    t.meta("warn", "handler_error", `session_events payload serialization failed: ${detail}`);
    payloadText = "{}";
  }

  t.enqueue(
    `INSERT INTO session_events (
      event_id, session_id, unix_ms, type, payload
    ) VALUES (?, ?, ?, ?, ?)`,
    [randomUUID(), sessionId, t.now(), type, payloadText],
  );
}

export function registerSessionEventsCapture(pi: ExtensionAPI, t: Telemetry): void {
  pi.on("session_before_compact", async (event: SessionBeforeCompactEvent) => {
    guard(t, () => {
      const payload: Record<string, unknown> = {
        reason: event.reason,
        tokens_before: event.preparation?.tokensBefore ?? null,
        will_retry: event.willRetry,
      };
      insertEvent(t, "compaction", payload);
    });
  });

  pi.on("session_compact", async (event: SessionCompactEvent) => {
    guard(t, () => {
      const payload: Record<string, unknown> = {
        reason: event.reason,
        tokens_before: event.compactionEntry?.tokensBefore ?? null,
        will_retry: event.willRetry,
        from_extension: event.fromExtension,
      };
      insertEvent(t, "compaction", payload);
    });
  });

  pi.on("model_select", async (event: ModelSelectEvent) => {
    guard(t, () => {
      const payload: Record<string, unknown> = {
        source: event.source,
      };
      if (event.previousModel) {
        payload.from = {
          provider: event.previousModel.provider,
          id: event.previousModel.id,
        };
      }
      payload.to = {
        provider: event.model.provider,
        id: event.model.id,
      };
      insertEvent(t, "model_change", payload);
    });
  });

  pi.on("thinking_level_select", async (event: ThinkingLevelSelectEvent) => {
    guard(t, () => {
      const payload: Record<string, unknown> = {
        from_level: event.previousLevel,
        to_level: event.level,
      };
      insertEvent(t, "thinking_change", payload);
    });
  });

  pi.on("session_before_fork", async (event: SessionBeforeForkEvent) => {
    guard(t, () => {
      const payload: Record<string, unknown> = {
        entry_id: event.entryId,
        position: event.position,
      };
      insertEvent(t, "branch", payload);
    });
  });

  pi.on("session_tree", async (event: SessionTreeEvent) => {
    guard(t, () => {
      const payload: Record<string, unknown> = {
        old_leaf_id: event.oldLeafId ?? null,
        new_leaf_id: event.newLeafId ?? null,
      };
      const entryId = event.summaryEntry?.id;
      if (entryId) {
        payload.entry_id = entryId;
      }
      insertEvent(t, "tree_nav", payload);
    });
  });
}

